 shots.append({'id':q['id'],'verse':q['sourceVerseRef'],'exactHatam':q['text'],'speaker':name,'characterId':binding['characterId'],'versionId':binding['versionId'],'voiceId':binding['voice_id'],'sourceWindow':q['exactSourceWindow'],'sourceBasedContainerEstimate':s['sectionCount'],'sourceBasedQuietJoinStatus':s['status'],'actingIntent':acting[q['id']],'referenceIds':[a['id'] for a in binding['assets']],'approvedTakeReuse':reused[0] if reused else None,'speechGeneration':'Reuse exact approved take for matching source/voice, otherwise hold until chapter-voice allowance. No TTS, new words or paid fallback.','framing':'16:9; one speaking face; medium close view preserving face/hair silhouette. Chest/shoulders and eyeline follow source scene and shared geography. Final crop requires actual native frame evidence, no global crop.','continuity':'Continue from preceding last retained frame within each speaking chain. Each approved full-line performance remains one continuous soundtrack.','musicReferenceApproval':'../music-preview-v3/producer-level-approval.json','finalCastPerformancePlan':'Recompute from exact approved returned full-line audio, not from this source estimate.','status':'reviewable_speaking_brief_not_generated_or_formal_crew_accepted'})
