 q=next(q for q in measure['quotes'] if q['id']==id);sections=q['plan']['sections'];safe=not q['internalJoinsWithoutMeasuredQuiet']
 joins.append({'id':id,'sourceBasedSections':q['sectionCount'],'allInternalJoinsInMeasuredQuiet':safe,'sourceSections':[{'startSample':s['sourceStartSample'],'endSample':s['sourceEndSample'],'frames':s['retainedFrames'],'reason':s['boundaryReason']} for s in sections],'treatment':'Source-based quiet-only route found; replan on approved cast bytes and review assembled line.' if safe else 'No quiet-only route within four seconds for entire source line. Propose listener/context coverage for long quiet-free span; retain full audio and explicit source/role review. No automatic syllable cut.'})
